// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the system time.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A zero-value Limiter is invalid; use New.
type Limiter struct {
	mu        sync.Mutex
	rate      float64   // tokens per second
	burst     float64   // bucket capacity
	tokens    float64   // current tokens
	last      time.Time // last refill time
	clock     Clock
}

// ErrInvalidConfig is returned by New for non-positive rate or burst.
var ErrInvalidConfig = errors.New("ratelimit: rate and burst must be positive")

// New creates a Limiter that emits rate tokens per second with capacity burst.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 || burst <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst), // start full
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed now, consuming them if so.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.last = now
	}

	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(1) }
