// fakeClock is a manually advanced clock.
type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func newFakeClock(start time.Time) *fakeClock { return &fakeClock{now: start} }

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now = c.now.Add(d)
}

func TestNewValidation(t *testing.T) {
	tests := []struct {
		name    string
		rate    float64
		burst   int
		wantErr bool
	}{
		{"valid", 1, 1, false},
		{"zero rate", 0, 1, true},
		{"negative rate", -1, 1, true},
		{"zero burst", 1, 0, true},
		{"negative burst", 1, -1, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := New(tc.rate, tc.burst, newFakeClock(time.Unix(0, 0)))
			if (err != nil) != tc.wantErr {
				t.Fatalf("New(%v, %d) err = %v, wantErr %v", tc.rate, tc.burst, err, tc.wantErr)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Unix(0, 0)
	tests := []struct {
		name     string
		rate     float64
		burst    int
		advance  time.Duration
		requests []int
		want     []bool
	}{
		{"burst consumed", 1, 3, 0, []int{1, 1, 1, 1}, []bool{true, true, true, false}},
		{"too large request", 1, 2, 0, []int{3}, []bool{false}},
		{"refill over time", 2, 2, 0, []int{2, 1}, []bool{true, false}},
		{"refill after advance", 2, 2, 500 * time.Millisecond, []int{2, 1}, []bool{true, true}},
		{"partial refill", 1, 2, 500 * time.Millisecond, []int{2, 1}, []bool{false, true}},
		{"zero request", 1, 1, 0, []int{0}, []bool{true}},
		{"negative request", 1, 1, 0, []int{-1}, []bool{false}},
		{"no overfill beyond burst", 10, 1, 10 * time.Second, []int{1, 2}, []bool{true, false}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			clk := newFakeClock(base)
			l, err := New(tc.rate, tc.burst, clk)
			if err != nil {
				t.Fatalf("New: %v", err)
			}
			clk.Advance(tc.advance)
			for i, n := range tc.requests {
				if got := l.AllowN(n); got != tc.want[i] {
					t.Errorf("request %d: AllowN(%d) = %v, want %v", i, n, got, tc.want[i])
				}
			}
		})
	}
}

func TestAllow(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	l, err := New(1, 1, clk)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	if !l.Allow() {
		t.Fatal("first Allow = false, want true")
	}
	if l.Allow() {
		t.Fatal("second Allow = true, want false")
	}
	clk.Advance(time.Second)
	if !l.Allow() {
		t.Fatal("Allow after 1s = false, want true")
	}
}

func TestConcurrent(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	l, err := New(1000, 100, clk)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	var wg sync.WaitGroup
	var mu sync.Mutex
	allowed := 0
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.Allow() {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed != 100 {
		t.Errorf("allowed = %d, want 100", allowed)
	}
}
